package com.tripmateai.entity;
import com.tripmateai.enums.*; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="bookings",uniqueConstraints=@UniqueConstraint(name="uk_booking_reference",columnNames="booking_reference"),indexes={@Index(name="idx_bookings_trip",columnList="trip_id"),@Index(name="idx_bookings_status",columnList="status")}) @Getter @Setter @NoArgsConstructor @EqualsAndHashCode(callSuper=true,onlyExplicitlyIncluded=true) @ToString
public class Booking extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="trip_id",nullable=false) @ToString.Exclude private Trip trip; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) @ToString.Exclude private User user; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private BookingType type; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private BookingStatus status=BookingStatus.PLANNED; @NotBlank @Size(max=200) @Column(nullable=false,length=200) private String provider; @Size(max=100) @Column(name="booking_reference",unique=true,length=100) private String bookingReference; @Column(name="start_at") private LocalDateTime startAt; @Column(name="end_at") private LocalDateTime endAt; @DecimalMin("0.00") @Column(precision=12,scale=2) private BigDecimal amount; @Column(length=3) private String currency="INR"; @Size(max=2048) @Column(name="document_url",length=2048) private String documentUrl; }
